var vocabulary = new Map(
  Object.entries(loanwordData.entries).map(([word, entry]) => [
    word,
    {
      original: entry.original,
      language: entry.language,
      kind: entry.kind === "original" ? "original" : "meaning"
    }
  ])
);
for (const [word, entry] of overrides) vocabulary.set(word, entry);
var katakana = /^[ァ-ヺーｦ-ﾟ・･]+$/u;
function annotateLoanwords(segments) {
  const result = [];
  for (let index = 0; index < segments.length; ) {
    const segment = segments[index];
    if (segment.reading || !katakana.test(segment.text)) {
      result.push(segment);
      index++;
      continue;
    }
    let end = index + 1;
    while (end < segments.length && !segments[end].reading && katakana.test(segments[end].text)) end++;
    const word = segments.slice(index, end).map(({ text }) => text).join("");
    const entry = vocabulary.get(word.normalize("NFKC"));
    if (entry)
      result.push({
        text: word,
        reading: entry.original,
        readingLanguage: entry.language,
        ...entry.kind ? { readingKind: entry.kind } : {}
      });
    else result.push(...segments.slice(index, end));
    index = end;
  }
  return result;
}

// server/annotate.ts
var require2 = createRequire(import.meta.url);
var dictionaryPath = join(dirname(require2.resolve("kuromoji/package.json")), "dict");
var tokenizerPromise;
function getTokenizer() {
  tokenizerPromise ??= new Promise((resolve, reject) => {
    kuromoji.builder({ dicPath: dictionaryPath }).build((error, tokenizer) => {
      if (error) reject(error);
      else resolve(tokenizer);
    });
  });
  return tokenizerPromise;
}
function toHiragana(value) {
  return value.replace(/[ァ-ヶ]/g, (character) => String.fromCharCode(character.charCodeAt(0) - 96));
}
async function annotateJapanese(text) {
  if (!text) return [];
  const tokenizer = await getTokenizer();
  const tokens = tokenizer.tokenize(text);
  const segments = [];
  let cursor = 0;
  for (const token of tokens) {
    const index = text.indexOf(token.surface_form, cursor);
    if (index > cursor) segments.push({ text: text.slice(cursor, index) });
    const reading = token.reading;
    segments.push({
      text: token.surface_form,
      ...reading && new RegExp("\\p{Script=Han}", "u").test(token.surface_form) ? { reading: toHiragana(reading) } : {}
    });
    cursor = index + token.surface_form.length;
  }
  if (cursor < text.length) segments.push({ text: text.slice(cursor) });
  return annotateLoanwords(segments);
}
function formatWithReadings(segments) {
  return segments.map(({ text, reading }) => reading ? `${text}(${reading})` : text).join("");
}

// cli.ts
async function main() {
  const filePath = process.argv[2];
  if (!filePath || filePath === "--help" || filePath === "-h") {
    console.log("Usage: jm <file>");
    console.log("Add hiragana readings beside kanji and print the result.");
    process.exitCode = filePath ? 0 : 1;
    return;
  }
  try {
    const text = await readFile(filePath, "utf8");
    const segments = await annotateJapanese(text);
    process.stdout.write(formatWithReadings(segments));
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`jm: could not read ${basename(filePath)}: ${message}`);
    process.exitCode = 1;
  }
}
void main();
